uv run python -c 'import sys,tempfile; from pathlib import Path; sys.path[:0]=["tests"]; import test_trust_mutants as T; r=Path(tempfile.mkdtemp())/"p"; T.scaffold(r,""); (r/"lean/Demo/Defs.lean").write_text("namespace Demo\n\nclass Ordered (α : Type) where\n  le : α → α → Prop\n  leb : α → α → Bool\n  leb_iff : ∀ a b, leb a b = true ↔ le a b\n\ninstance [Ordered α] (a b : α) : Decidable (Ordered.le a b) := decidable_of_iff _ (Ordered.leb_iff a b)\n\ndef fastLe (a b : Nat) : Bool := a ≤ b\n\ntheorem fastLe_iff (a b : Nat) : fastLe a b = true ↔ a ≤ b := by\n  simp [fastLe]\n\ninstance : Ordered Nat := ⟨(· ≤ ·), fastLe, fastLe_iff⟩\n\n#guard Ordered.le 2 3\n\nend Demo\n"); T.dump(r,Path(tempfile.mkdtemp()),[]); T.git(r,"add","."); T.git(r,"commit","-qm","head"); s=[(m["operator"],m["status"],m["detail"][:90]) for m in T.of(T.tool(r,r.parent/"run")[1],"fastLe")]; print(s); assert s and not any(x=="KILLED" for _,x,_ in s), s'
